{"policy":"permit (
    principal is User,
    action == Action::"approveCommissionRequest",
    resource is CommissionRequest
)
when {
    principal.roles.contains("facility_manager")
};

forbid (
    principal is User,
    action == Action::"approveCommissionRequest",
    resource is CommissionRequest
)
when {
    principal.roles.contains("facility_manager") &&
    resource.status != "requested"
};

forbid (
    principal is User,
    action == Action::"approveCommissionRequest",
    resource is CommissionRequest
)
when {
    principal.roles.contains("facility_manager") &&
    !context.fromOnSiteBuildingNetwork
};

forbid (
    principal is User,
    action == Action::"approveCommissionRequest",
    resource is CommissionRequest
)
when {
    principal.roles.contains("facility_manager") &&
    !context.withinPermittedWindow
};"}
